draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var e = 1.6e-19, mp = 1.67e-27;
var m = p.mass * mp;
var v = p.speed * 1e6;
var B = p.field;
var r = m * v / (e * B);
var T = 2 * Math.PI * m / (e * B);
var f = 1 / T;

var S = (0.40 * H) / 0.10;
var rp = r * S;
var x0 = W * 0.14, y0 = H * 0.52;
var cx = x0, cy = y0 + rp;

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
var i, j;
for (i = 0; i < 9; i++) {
  for (j = 0; j < 5; j++) {
    var dx = W * 0.06 + i * W * 0.11, dy = H * 0.10 + j * H * 0.20;
    ctx.beginPath(); ctx.arc(dx, dy, 1.6, 0, Math.PI * 2); ctx.stroke();
  }
}

ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.lineWidth = 1;
ctx.beginPath();
ctx.arc(cx, cy, rp, 0, Math.PI * 2);
ctx.stroke();
ctx.setLineDash([]);

var Tvis = T * 3e6;
var ph = (t / Tvis) * 2 * Math.PI;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
var k;
for (k = 0; k <= 60; k++) {
  var a = -Math.PI / 2 + (ph % (2 * Math.PI)) * k / 60;
  var px = cx + rp * Math.cos(a), py = cy + rp * Math.sin(a);
  if (k === 0) { ctx.moveTo(px, py); } else { ctx.lineTo(px, py); }
}
ctx.stroke();

var ang = -Math.PI / 2 + ph;
var bx = cx + rp * Math.cos(ang), by = cy + rp * Math.sin(ang);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx, by, 5, 0, Math.PI * 2); ctx.fill();

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(cx, cy); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("F points at the centre", cx + 8, cy - 6);

var bar = 0.05 * S;
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(W - 20 - bar, H - 16); ctx.lineTo(W - 20, H - 16); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.lineWidth = 1;
ctx.fillText("5 cm", W - 20 - bar, H - 22);
ctx.fillText("B out of the page", 10, 14);

out.note = "r = " + r.toFixed(4) + " m,  T = " + T.toExponential(3) + " s,  f = " + (f / 1e6).toFixed(2) + " MHz  (change the speed: T does not move)";
